{
  "titre": "Rituel tables de multiplication",
  "objectifGeneral": "Réactiver les connaissances sur les tables de multiplication",
  "notionsPivots": [
    "les tables de multiplication",
    "un produit",
    "une égalité",
    "un nombre entier",
    "un facteur"
  ],
  "etapes": [
    {
      "titre": "Vérification rapide",
      "objectif": "Identifier les égalités correctes",
      "cartes": [
        {
          "titre": "Vrai ou faux ?",
          "objectif": "Vérifier la justesse d'une égalité",
          "module": "TrueFalse",
          "palier": "entrainement",
          "duree": 2,
          "consigne": "L’enseignant lit à voix haute 10 égalités simples (exemples : 7 x 8 = 56, 9 x 5 = 44). Après chaque énoncé, vous cochez Vrai ou Faux directement sur la carte. L’enseignant corrige collectivement à la fin."
        }
      ]
    },
    {
      "titre": "Comblage des cases",
      "objectif": "Retrouver les facteurs manquants",
      "cartes": [
        {
          "titre": "Trouve le bon nombre",
          "objectif": "Compléter une multiplication",
          "module": "FillInTheBlanks",
          "palier": "entrainement",
          "duree": 4,
          "consigne": "5 opérations à trous s’affichent (exemple : 6 x __ = 42). Utilisez les chiffres proposés dans le menu déroulant pour compléter chaque égalité. Validez après chaque réponse."
        }
      ]
    },
    {
      "titre": "Choix multiples",
      "objectif": "Sélectionner le résultat exact",
      "cartes": [
        {
          "titre": "Le bon produit",
          "objectif": "Choisir la bonne réponse parmi des propositions",
          "module": "SingleChoiceSet",
          "palier": "entrainement",
          "duree": 4,
          "consigne": "Pour 5 produits à calculer mentalement, une liste de 3 ou 4 résultats possibles est proposée. Cliquez sur celui qui correspond à l’opération (exemple : 8 x 7 → choisissez parmi 54, 56, 58)."
        }
      ]
    }
  ]
}
